using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using ROM.Horde;using ROM.UI.Sprint01;using MultiFPS.UI;
namespace ROM.Rendering {
 [DisallowMultipleComponent,DefaultExecutionOrder(850)]public sealed class RiftAtmospherePilot:MonoBehaviour {
