  public bool Applied{get;private set;}public string Status{get;private set;}="Waiting";
  RiftNightAtmosphere night;FracturedHeart heart;Volume user,art;VolumeProfile userOriginal,artOriginal,userCopy,artCopy;Material skyOriginal,skyCopy;
  RiftCheckpoint origin;int revision;bool oldFog;FogMode oldFogMode;float oldFogStart,oldFogEnd,oldFogDensity,oldAmbientIntensity,oldNightExposure,oldSkyExposure,oldMoonIntensity,oldShadow,oldHeartBase;Color oldFogColor,oldSky,oldHorizon,oldGround,oldMoonColor,oldHeartCalm;
  sealed class LightState {public Light Light;public Color Color;public float Intensity,Range;public LightRenderMode Mode;}
  readonly List<LightState> lights=new List<LightState>();readonly Dictionary<Renderer,Material[]> materials=new Dictionary<Renderer,Material[]>();readonly List<UnityEngine.Object> owned=new List<UnityEngine.Object>();Light createdSpill,createdFill;
  public void SetPreviewEnabled(bool value){Enabled=value;if(!value)Restore();else TryApply();}
  void Update(){if(!Application.isPlaying)return;if(!ShouldApply()){if(Applied)Restore();return;}if(!Applied)TryApply();else if(Settings.Revision!=revision){Restore();TryApply();}}
  bool ShouldApply(){if(!Enabled||!Settings||SceneManager.GetActiveScene().name!=Settings.SceneName)return false;var actor=ClientFrontend.OwnedCharacterInstance;if(!actor)return false;if(!origin)origin=UnityEngine.Object.FindObjectsByType<RiftCheckpoint>(FindObjectsSortMode.None).FirstOrDefault(c=>c.StartingCamp);return origin&&Vector3.Distance(actor.transform.position,origin.transform.position)<Settings.Radius;}
  static VolumeProfile Copy(VolumeProfile source,List<UnityEngine.Object> owned){var p=ScriptableObject.CreateInstance<VolumeProfile>();owned.Add(p);foreach(var c in source.components){var clone=UnityEngine.Object.Instantiate(c);owned.Add(clone);p.components.Add(clone);}return p;}
  static T Part<T>(VolumeProfile p)where T:VolumeComponent,new(){if(p.TryGet<T>(out var c))return c;return p.Add<T>();}
  void TryApply(){try{ApplyInternal();}catch(Exception e){Restore();Enabled=false;Status="Pilot failed safely: "+e.Message;Debug.LogError(Status);}}
  void ApplyInternal(){if(!Application.isPlaying||Applied||!ShouldApply())return;night=UnityEngine.Object.FindFirstObjectByType<RiftNightAtmosphere>();heart=UnityEngine.Object.FindFirstObjectByType<FracturedHeart>();var volumes=UnityEngine.Object.FindObjectsByType<Volume>(FindObjectsSortMode.None);user=volumes.FirstOrDefault(v=>v.name=="ROM User Effects"&&v.priority==100);art=volumes.FirstOrDefault(v=>v.name=="El Rift - Direccion de arte"&&v.priority==10);if(!night||!night.Moon||!user||!art||!RiftVideoSettings.Instance){Status="Waiting for scene/user volumes";return;}
   userOriginal=user.profile;artOriginal=art.profile;userCopy=Copy(userOriginal,owned);artCopy=Copy(artOriginal,owned);user.profile=userCopy;art.profile=artCopy;
   oldFog=RenderSettings.fog;oldFogMode=RenderSettings.fogMode;oldFogStart=RenderSettings.fogStartDistance;oldFogEnd=RenderSettings.fogEndDistance;oldFogColor=RenderSettings.fogColor;oldFogDensity=night.FogDensity;oldAmbientIntensity=RenderSettings.ambientIntensity;oldSky=night.SkyAmbient;oldHorizon=night.HorizonAmbient;oldGround=night.GroundAmbient;oldNightExposure=night.BaseExposure;oldSkyExposure=night.SkyExposure;oldMoonIntensity=night.MoonIntensity;oldMoonColor=night.MoonColor;oldShadow=night.Moon.shadowStrength;
   Applied=true;
   if(heart){oldHeartBase=heart.BaseLight;oldHeartCalm=heart.Calm;heart.BaseLight=Settings.KeyIntensity;heart.Calm=Settings.KeyColor;}
   skyOriginal=RenderSettings.skybox;if(skyOriginal){skyCopy=new Material(skyOriginal);owned.Add(skyCopy);RenderSettings.skybox=skyCopy;}
   night.BaseExposure=Settings.BaseExposure;night.SkyExposure=Settings.SkyExposure;night.SkyAmbient=Settings.AmbientSky;night.HorizonAmbient=Settings.AmbientHorizon;night.GroundAmbient=Settings.AmbientGround;night.MoonIntensity=Settings.KeyIntensity;night.MoonColor=Settings.KeyColor;night.Apply();night.Moon.shadowStrength=Settings.ShadowStrength;RenderSettings.ambientIntensity=Settings.AmbientIntensity;
   var fillObject=new GameObject("Pilot world sky bounce",typeof(Light));fillObject.transform.SetParent(transform,false);fillObject.transform.rotation=Quaternion.Euler(48,night.Moon.transform.eulerAngles.y+150,0);createdFill=fillObject.GetComponent<Light>();createdFill.type=LightType.Directional;createdFill.color=Settings.FillColor;createdFill.intensity=Settings.FillIntensity;createdFill.shadows=LightShadows.None;createdFill.renderMode=LightRenderMode.ForcePixel;
   RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogColor=Settings.FogColor;RenderSettings.fogStartDistance=Settings.FogStart;RenderSettings.fogEndDistance=Settings.FogEnd;
   Part<ColorAdjustments>(artCopy).contrast.Override(Settings.Contrast);Part<ColorAdjustments>(artCopy).saturation.Override(Settings.Saturation);Part<Vignette>(artCopy).intensity.Override(Settings.Vignette);var split=Part<SplitToning>(artCopy);split.shadows.Override(Settings.ShadowTone);split.highlights.Override(Settings.HighlightTone);split.balance.Override(0);
   foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None)){if(Vector3.Distance(r.bounds.center,origin.transform.position)>Settings.Radius)continue;bool changed=false;var next=r.sharedMaterials.Select(m=>{if(!m)return m;bool crystal=m.shader&&m.shader.name=="ROM/Rift Crystal Ground Radiance";var rule=(Settings.MaterialRules??Array.Empty<RiftAtmospherePilotSettings.MaterialRule>()).FirstOrDefault(x=>x!=null&&x.Source==m);if(!crystal&&rule==null)return m;var clone=new Material(m);owned.Add(clone);changed=true;if(crystal){if(Settings.CrystalShader)clone.shader=Settings.CrystalShader;clone.SetColor("_EmissionColor",Settings.CrystalEnergy);clone.SetColor("_RimColor",Settings.CrystalEdge);}if(rule!=null){if(clone.HasProperty("_Metallic"))clone.SetFloat("_Metallic",rule.Metallic);if(clone.HasProperty("_Smoothness"))clone.SetFloat("_Smoothness",rule.Smoothness);}return clone;}).ToArray();if(changed){materials[r]=r.sharedMaterials;r.sharedMaterials=next;}}
   var ground=origin.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="CrystalGround - Refugio inicial");Vector3 focus=ground?ground.position+Vector3.up*2:origin.transform.position+Vector3.up*2;
   var spill=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Where(l=>l.type==LightType.Point&&l.name=="Checkpoint violet spill"&&Vector3.Distance(l.transform.position,focus)<10).OrderBy(l=>Vector3.Distance(l.transform.position,focus)).FirstOrDefault();
   if(spill){lights.Add(new LightState{Light=spill,Color=spill.color,Intensity=spill.intensity,Range=spill.range,Mode=spill.renderMode});}else{var go=new GameObject("Pilot crystal motivated spill",typeof(Light));go.transform.SetParent(transform,false);go.transform.position=focus;spill=createdSpill=go.GetComponent<Light>();spill.type=LightType.Point;spill.shadows=LightShadows.None;}
   spill.color=Settings.SpillColor;spill.intensity=Settings.SpillIntensity;spill.range=Settings.SpillRange;spill.renderMode=LightRenderMode.ForcePixel;
   Applied=true;revision=Settings.Revision;Status="Applied locally: starting checkpoint zone; scene assets unchanged";ComposeUser();DynamicGI.UpdateEnvironment();
  }
  void LateUpdate(){if(Applied)ComposeUser();}
  void ComposeUser(){if(!user||!userCopy||!Settings)return;var p=RiftVideoSettings.Instance?RiftVideoSettings.Instance.Current:null;if(p==null)return;Part<ColorAdjustments>(userCopy).postExposure.Override(Settings.BaseExposure+p.Exposure);var bloom=Part<Bloom>(userCopy);bloom.intensity.Override(p.Bloom?Settings.BloomIntensity:0);bloom.threshold.Override(Settings.BloomThreshold);Part<MotionBlur>(userCopy).intensity.Override(0);}
  [ContextMenu("Restore original runtime state")]public void Restore(){if(!Applied)return;Applied=false;bool sameScene=gameObject.scene==SceneManager.GetActiveScene();if(user&&userOriginal)user.profile=userOriginal;if(art&&artOriginal)art.profile=artOriginal;if(night){night.BaseExposure=oldNightExposure;night.SkyExposure=oldSkyExposure;night.SkyAmbient=oldSky;night.HorizonAmbient=oldHorizon;night.GroundAmbient=oldGround;night.MoonIntensity=oldMoonIntensity;night.MoonColor=oldMoonColor;night.FogDensity=oldFogDensity;if(sameScene)night.Apply();if(night.Moon)night.Moon.shadowStrength=oldShadow;}if(heart){heart.BaseLight=oldHeartBase;heart.Calm=oldHeartCalm;}if(sameScene){RenderSettings.fog=oldFog;RenderSettings.fogMode=oldFogMode;RenderSettings.fogColor=oldFogColor;RenderSettings.fogStartDistance=oldFogStart;RenderSettings.fogEndDistance=oldFogEnd;RenderSettings.fogDensity=oldFogDensity;RenderSettings.ambientIntensity=oldAmbientIntensity;if(skyOriginal)RenderSettings.skybox=skyOriginal;}
   foreach(var pair in materials)if(pair.Key)pair.Key.sharedMaterials=pair.Value;materials.Clear();foreach(var saved in lights)if(saved.Light){saved.Light.color=saved.Color;saved.Light.intensity=saved.Intensity;saved.Light.range=saved.Range;saved.Light.renderMode=saved.Mode;}lights.Clear();if(createdSpill)Destroy(createdSpill.gameObject);createdSpill=null;if(createdFill)Destroy(createdFill.gameObject);createdFill=null;foreach(var o in owned)if(o)Destroy(o);owned.Clear();Status="Restored";DynamicGI.UpdateEnvironment();
  }
  void OnDisable(){if(Application.isPlaying)Restore();}void OnDestroy(){if(Application.isPlaying)Restore();}
 }
